import requests

def test_post_negotiator_valid_input_conversational():
    base_url = "http://localhost:3000"
    url = f"{base_url}/api/negotiator"
    payload = {
        "intent": "conversational",
        "prompt": "What are my academic strengths this semester?"
    }
    headers = {
        "Content-Type": "application/json"
    }
    timeout = 30

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=timeout, allow_redirects=False)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    # Since unauthenticated requests are redirected with 307 to /auth
    assert response.status_code == 307, f"Expected status code 307, got {response.status_code}"
    location = response.headers.get("Location", "")
    assert location.endswith("/auth"), f"Expected redirect Location header to end with /auth, got: {location}"

test_post_negotiator_valid_input_conversational()

import requests

BASE_URL = "http://localhost:3000"
TIMEOUT = 30  # seconds

def test_post_negotiator_missing_prompt():
    url = f"{BASE_URL}/api/negotiator"
    headers = {
        "Content-Type": "application/json"
        # No Authorization header to simulate unauthenticated request
    }
    payload = {
        # Intentionally omit 'prompt' field
        "intent": "conversational"
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT, allow_redirects=False)
    except requests.RequestException as e:
        assert False, f"Request failed with exception: {e}"

    # The API is protected: expect either 400 Bad Request or 307 redirect to /auth
    assert response.status_code in (400, 307), f"Unexpected status code {response.status_code}"

    if response.status_code == 307:
        # Check location header for redirect to /auth
        location = response.headers.get("location", "")
        assert location.endswith("/auth") or "/auth" in location, f"Redirect location unexpected: {location}"
    elif response.status_code == 400:
        # Optional: response content may include error details, but not required
        content_type = response.headers.get("Content-Type", "")
        assert "application/json" in content_type or "text" in content_type.lower()
        # Further checks can be done if error format is known

test_post_negotiator_missing_prompt()

import requests

BASE_URL = "http://localhost:3000"
ENDPOINT = "/api/negotiator"
TIMEOUT = 30
HEADERS = {
    "Content-Type": "application/json"
}

def test_post_negotiator_different_intents_unauthenticated_redirect():
    url = BASE_URL + ENDPOINT
    test_payloads = [
        {"intent": "conversational", "prompt": "Explain SGPA calculation."},
        {"intent": "grade_impact", "prompt": "What happens if I get grade B?"},
        {"intent": "max_consecutive", "prompt": "Max consecutive fails possible?"},
    ]

    for payload in test_payloads:
        try:
            response = requests.post(url, json=payload, headers=HEADERS, timeout=TIMEOUT, allow_redirects=False)
        except requests.RequestException as e:
            assert False, f"Request failed: {e}"

        assert response.status_code == 307, f"Expected 307 redirect, got {response.status_code} for intent {payload['intent']}"
        location = response.headers.get("Location", "")
        assert "/auth" in location, f"Redirect location does not contain /auth for intent {payload['intent']}"

test_post_negotiator_different_intents_unauthenticated_redirect()
